mapper.insert:

	select seq_beauty_test.nextval from dual

insert into beauty_test (
	beauty_test_seq, member_seq, score, score100, grade, photo_count, created_at, updated_at
) values (
	#{beautyTestSeq}, #{memberSeq}, #{score}, #{score100}, #{grade}, #{photoCount}, systimestamp, systimestamp
)

mapper.select:
select *
  from (
	select beauty_test_seq, member_seq, score, score100, grade, photo_count, created_at, updated_at
	  from beauty_test
	 where member_seq = #{memberSeq}
	 order by beauty_test_seq desc
  )
 where rownum = 1
